from dataclasses import dataclass


@dataclass
class Num:
    v: int


@dataclass
class Add:
    l: 'Expr'
    r: 'Expr'


@dataclass
class Mul:
    l: 'Expr'
    r: 'Expr'


Expr = Num | Add | Mul


def eval_expr(e: Expr) -> int:
    """Evaluate an expression tree: Num yields its value, Add the sum of
    its operands, Mul the product of its operands."""
    match e:
        case Num(v=v):
            return v
        case Add(l=l, r=r):
            return eval_expr(l) + eval_expr(r)
        case Mul(l=l, r=r):
            return eval_expr(l) * eval_expr(r)


def test_num() -> None:
    assert eval_expr(Num(5)) == 5
    assert eval_expr(Num(0)) == 0
    assert eval_expr(Num(-3)) == -3


def test_add() -> None:
    assert eval_expr(Add(Num(2), Num(3))) == 5
    assert eval_expr(Add(Num(-2), Num(2))) == 0


def test_mul() -> None:
    assert eval_expr(Mul(Num(4), Num(5))) == 20
    assert eval_expr(Mul(Num(0), Num(99))) == 0
    assert eval_expr(Mul(Num(-3), Num(4))) == -12


def test_nested() -> None:
    # (2 + 3) * 4 = 20
    assert eval_expr(Mul(Add(Num(2), Num(3)), Num(4))) == 20
    # 2 + (3 * 4) = 14
    assert eval_expr(Add(Num(2), Mul(Num(3), Num(4)))) == 14
    # (1 + 2) * (3 + 4) = 21
    assert eval_expr(Mul(Add(Num(1), Num(2)), Add(Num(3), Num(4)))) == 21


def test_precedence_is_structural() -> None:
    a = Add(Num(1), Mul(Num(2), Num(3)))
    b = Mul(Add(Num(1), Num(2)), Num(3))
    assert eval_expr(a) == 7
    assert eval_expr(b) == 9


def test_large_values() -> None:
    big = 10**12
    assert eval_expr(Mul(Num(big), Num(big))) == 10**24


def test_deep_tree() -> None:
    e: Expr = Num(0)
    for i in range(1, 101):
        e = Add(e, Num(i))
    assert eval_expr(e) == 5050


def test_does_not_mutate() -> None:
    e = Add(Num(1), Mul(Num(2), Num(3)))
    eval_expr(e)
    assert e == Add(Num(1), Mul(Num(2), Num(3)))
